fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    // Handle the special case where min_val > max_val
    if min_val > max_val {
        // Return a vector filled with max_val of the same length
        return vec![max_val; arr.len()];
    }
    
    // Normal case: min_val <= max_val
    // Apply clipping to each element
    arr.iter()
        .map(|&x| {
            if x < min_val {
                min_val
            } else if x > max_val {
                max_val
            } else {
                x
            }
        })
        .collect()
}